import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security Incident Playbook","description":"","frontmatter":{},"headers":[],"relativePath":"security/incident-playbook.md","filePath":"security/incident-playbook.md","lastUpdated":1786751537000}`),a={name:`security/incident-playbook.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /security/incident-playbook.md for this page in Markdown format</div><h1 id="security-incident-playbook" tabindex="-1">Security Incident Playbook <a class="header-anchor" href="#security-incident-playbook" aria-label="Permalink to “Security Incident Playbook”">​</a></h1><p>This is an operational starting point for applications built from React Starter Kit. It deliberately does not invent a security address, response-time promise, team structure, or disclosure policy. Define those for your organization before launch.</p><h2 id="prepare-before-an-incident" tabindex="-1">Prepare Before an Incident <a class="header-anchor" href="#prepare-before-an-incident" aria-label="Permalink to “Prepare Before an Incident”">​</a></h2><p>Record this information somewhere responders can reach when the application or primary repository is unavailable:</p><table tabindex="0"><thead><tr><th>Item</th><th>Owner or location</th></tr></thead><tbody><tr><td>Security report channel</td><td><em>Define before launch</em></td></tr><tr><td>Incident lead and backup</td><td><em>Define before launch</em></td></tr><tr><td>Cloudflare account and audit logs</td><td><em>Define before launch</em></td></tr><tr><td>Neon project and restore procedure</td><td><em>Define before launch</em></td></tr><tr><td>Resend, Google, and Stripe accounts</td><td><em>Define as enabled</em></td></tr><tr><td>GitHub private vulnerability reporting</td><td><em>Enable or document an alternative</em></td></tr><tr><td>User notification and legal contacts</td><td><em>Define before launch</em></td></tr></tbody></table><p>Also keep tested access for at least two responders, require MFA on provider accounts, and store recovery codes outside the systems they recover.</p><h2 id="_1-receive-and-triage" tabindex="-1">1. Receive and Triage <a class="header-anchor" href="#_1-receive-and-triage" aria-label="Permalink to “1. Receive and Triage”">​</a></h2><ol><li>Move the report to the approved confidential channel. Do not discuss an unpatched vulnerability in a public issue or pull request.</li><li>Preserve the original report, timestamps, relevant request IDs, logs, and provider audit events. Restrict access to people working the incident.</li><li>Reproduce in an isolated environment with synthetic data when possible.</li><li>Identify affected environments, versions, tenants, data, credentials, and time range.</li><li>Assign severity from demonstrated impact and exploitability. Treat active exploitation, authentication bypass, remote code execution, exposed signing secrets, or broad sensitive-data access as urgent.</li><li>Name one incident lead and one person responsible for the activity log.</li></ol><p>The activity log should distinguish verified facts from hypotheses and record who made each containment or recovery change.</p><h2 id="_2-contain" tabindex="-1">2. Contain <a class="header-anchor" href="#_2-contain" aria-label="Permalink to “2. Contain”">​</a></h2><p>Choose the smallest action that stops further harm without destroying evidence:</p><ul><li>Disable or restrict the affected route, integration, account, or Worker.</li><li>Add a temporary Cloudflare WAF rule when traffic can be identified safely.</li><li>Revoke exposed credentials at their issuing provider, then replace the Worker secret in every affected environment. Changing a secret creates a new Worker version; verify which version receives traffic.</li><li>Invalidate sessions or rotate <code>BETTER_AUTH_SECRET</code> only when the impact warrants signing everyone out. Rotation invalidates existing signed state.</li><li>For database exposure, rotate the Neon role password, update both Hyperdrive configurations, and verify direct migration credentials separately.</li><li>For a malicious dependency or build credential, stop deployments until the build inputs and artifacts are trusted again.</li></ul><p>Do not run destructive cleanup merely to make the system look normal. Preserve the data needed to determine scope, and record every emergency change that must later be reconciled with version-controlled configuration.</p><h2 id="_3-investigate" tabindex="-1">3. Investigate <a class="header-anchor" href="#_3-investigate" aria-label="Permalink to “3. Investigate”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> Establish the earliest known exploitation and the last known safe state.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Trace the request path through web, app, API, provider, and database logs.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> Check sibling endpoints and repeated code patterns, not only the reported URL.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> Determine whether cached results, queues, webhooks, object storage, logs, backups, or third parties contain affected data.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> Identify which credentials and sessions existed during the affected window and whether they were used unexpectedly.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> Write a minimal proof of concept and a regression test without retaining real secrets or personal data.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> Document the root cause and why existing controls did not catch it.</label></li></ul><p>Cloudflare request IDs and the API request ID are useful correlation keys. Avoid copying full authorization headers, cookies, OTPs, or database URLs into the incident log.</p><h2 id="_4-eradicate-and-recover" tabindex="-1">4. Eradicate and Recover <a class="header-anchor" href="#_4-eradicate-and-recover" aria-label="Permalink to “4. Eradicate and Recover”">​</a></h2><ol><li>Fix the root cause and close equivalent paths.</li><li>Add tests that fail for the original exploit and pass for legitimate use.</li><li>Run the checks in the <a href="./checklist">security checklist</a>.</li><li>Deploy to staging and verify the containment still holds.</li><li>Apply production database changes only after reviewing compatibility with the currently deployed Worker versions.</li><li>Deploy service-binding targets before the web router: API, app, then web.</li><li>Verify authentication, authorization, enabled integrations, headers, rate-limits, logs, and key user flows in production.</li><li>Remove temporary controls only after the permanent fix is confirmed.</li><li>Reconcile dashboard changes with Wrangler, Terraform, and documentation so a later deploy cannot undo the response.</li></ol><p>A Worker rollback changes code and configuration version; it does not reverse a database migration or restore deleted data. Use the Neon restore procedure when data recovery is required, and test the restored branch before cutover.</p><h2 id="_5-notify-and-disclose" tabindex="-1">5. Notify and Disclose <a class="header-anchor" href="#_5-notify-and-disclose" aria-label="Permalink to “5. Notify and Disclose”">​</a></h2><p>Coordinate notification with the application owner&#39;s legal and privacy obligations. Communicate confirmed facts, affected scope, containment status, required user action, and the next update time. Do not promise a patch date or claim no data was accessed until evidence supports it.</p><p>For a vulnerability in the upstream starter kit:</p><ol><li>Use the repository&#39;s private vulnerability reporting channel when enabled.</li><li>Prepare a GitHub Security Advisory with affected versions, impact, fix, and workarounds.</li><li>Coordinate public disclosure after a fix is available or when continued secrecy no longer reduces harm.</li><li>Request a CVE through the advisory only when the project and issue qualify.</li></ol><p>For an application-specific incident, notify that application&#39;s users and operators rather than the starter-kit repository.</p><h2 id="_6-review" tabindex="-1">6. Review <a class="header-anchor" href="#_6-review" aria-label="Permalink to “6. Review”">​</a></h2><p>After recovery, produce a short record containing:</p><ul><li>the factual timeline;</li><li>root cause and contributing conditions;</li><li>affected data, users, environments, and integrations;</li><li>containment and recovery actions;</li><li>detection gaps;</li><li>durable follow-up items, owners, and due dates.</li></ul><p>Update this playbook only with lessons that generalize. Keep incident-specific names, credentials, evidence, and internal contacts in the restricted incident record, not in public repository documentation.</p><h2 id="useful-references" tabindex="-1">Useful References <a class="header-anchor" href="#useful-references" aria-label="Permalink to “Useful References”">​</a></h2><ul><li><a href="./checklist">Security checklist</a></li><li><a href="/auth/">Authentication</a></li><li><a href="/deployment/cloudflare">Cloudflare deployment</a></li><li><a href="/deployment/ci-cd">CI/CD and rollback</a></li><li><a href="/deployment/production-database">Production database</a></li><li><a href="https://docs.github.com/en/code-security/security-advisories" target="_blank" rel="noreferrer">GitHub Security Advisories</a></li><li><a href="https://developers.cloudflare.com/workers/configuration/secrets/" target="_blank" rel="noreferrer">Cloudflare Worker secrets</a></li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};